func newUser() unsafe.Pointer { return unsafe.Pointer(new(tenant.User)) }

func newNUser(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]tenant.User, n))) }

func ptrUser(p unsafe.Pointer, c int32) any {
	r := (*tenant.User)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.CurrentOrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Status))
	case 4:
		return &r.Name
	case 5:
		return &r.Username
	case 6:
		return (*string)(unsafe.Pointer(&r.TimeFormat))
	case 7:
		return &r.Password
	case 8:
		return &r.EmailAddress
	case 9:
		return &r.ProfilePicURL
	case 10:
		return &r.ThumbnailURL
	case 11:
		return &r.Timezone
	case 12:
		return &r.Locale
	case 13:
		return &r.IsLocked
	case 14:
		return &r.MustChangePassword
	case 15:
		return &r.Version
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	case 18:
		return &r.LastLoginAt
	case 19:
		return &r.JobTitle
	case 20:
		return &r.PhoneNumber
	case 21:
		return (*string)(unsafe.Pointer(&r.AvatarStyle))
	case 22:
		return (*string)(unsafe.Pointer(&r.AvailabilityStatus))
	case 23:
		return &r.FocusUntil
	case 24:
		return &r.AwayBackOn
	case 25:
		return (**string)(unsafe.Pointer(&r.AwayDelegateUserID))
	case 26:
		return &r.AwayNote
	case 27:
		return &r.PasswordChangedAt
	case 28:
		return &r.SessionEpoch
	case 29:
		return &r.AssistantHidden
	}
	return nil
}

func valueUser(p unsafe.Pointer, c int32) any {
	r := (*tenant.User)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.CurrentOrganizationID)
	case 3:
		return string(r.Status)
	case 4:
		return r.Name
	case 5:
		return r.Username
	case 6:
		return string(r.TimeFormat)
	case 7:
		return r.Password
	case 8:
		return r.EmailAddress
	case 9:
		if r.ProfilePicURL == "" {
			return nil
		}
		return r.ProfilePicURL
	case 10:
		if r.ThumbnailURL == "" {
			return nil
		}
		return r.ThumbnailURL
	case 11:
		return r.Timezone
	case 12:
		return r.Locale
	case 13:
		return r.IsLocked
	case 14:
		return r.MustChangePassword
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	case 18:
		if r.LastLoginAt == nil {
			return nil
		}
		return *r.LastLoginAt
	case 19:
		return r.JobTitle
	case 20:
		return r.PhoneNumber
	case 21:
		return string(r.AvatarStyle)
	case 22:
		return string(r.AvailabilityStatus)
	case 23:
		if r.FocusUntil == nil {
			return nil
		}
		return *r.FocusUntil
	case 24:
		if r.AwayBackOn == nil {
			return nil
		}
		return *r.AwayBackOn
	case 25:
		if r.AwayDelegateUserID == nil {
			return nil
		}
		return string(*r.AwayDelegateUserID)
	case 26:
		return r.AwayNote
	case 27:
		if r.PasswordChangedAt == nil {
			return nil
		}
		return *r.PasswordChangedAt
	case 28:
		return r.SessionEpoch
	case 29:
		return r.AssistantHidden
	}
	return nil
}

func attachUser(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*tenant.User)(p)
	switch rel {
	case 0:
		r.CurrentOrganization = (*tenant.Organization)(child)
	case 1:
		r.Memberships = append(r.Memberships, (*tenant.OrganizationMembership)(child))
	case 2:
		r.Assignments = append(r.Assignments, (*rbac.UserRoleAssignment)(child))
	}
}

func beforeCreateUser(ctx context.Context, p unsafe.Pointer) error {
	return (*tenant.User)(p).BeforeCreate(ctx)
}

func init() {
	organizationsTable.Relations[0].Target = usstatedb.UsStatesSchema()
	organizationsTable.Relations[1].Target = BusinessUnitsSchema()
	organizationMembershipsTable.Relations[0].Target = UsersSchema()
	organizationMembershipsTable.Relations[1].Target = UsersSchema()
	organizationMembershipsTable.Relations[2].Target = OrganizationsSchema()
	usersTable.Relations[0].Target = OrganizationsSchema()
	usersTable.Relations[1].Target = OrganizationMembershipsSchema()
	usersTable.Relations[2].Target = rbacdb.UserRoleAssignmentsSchema()
}

